const NAME = 'My Soul';
for (const s of $('Read STARTUPS').all()) {
  if (String(s.json.startup || '').trim().toLowerCase() === NAME.toLowerCase()) { throw new Error('My Soul already exists in STARTUPS - aborting'); }
}
for (const p of $('Read PIPELINE').all()) {
  if (String(p.json.startup || '').trim().toLowerCase() === NAME.toLowerCase()) { throw new Error('PIPELINE already has My Soul rows - aborting'); }
}

const SECTOR = 'Consumer Health | Sexual Wellness D2C';
const SUB = 'Consumer Health | Sexual Wellness D2C | Traction Stage | Revenue Run-Rate: INR 2.2 Cr | Projected Y3 Revenue: INR 24.6 Cr | Raising INR 8 Cr';

const H1 = 'Blinkit converts at 40-45% versus 4-6% on marketplaces; EjacuDelay ranks first on high-intent search in its lead category';
const H2 = '84% product margin and 40% contribution margin on INR 325 AOV with a 6.6% return rate';
const H3 = 'Clinical proposition for men and women across seven certification regimes, against pleasure-led single-gender incumbents';

const wrap = 'font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.65;color:#222222;';
const h = 'font-family:Arial,Helvetica,sans-serif;font-size:14px;font-weight:700;color:#000000;margin:22px 0 8px 0;';
const p = 'font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.65;color:#222222;margin:0 0 12px 0;';
const li = 'font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.65;color:#222222;margin:0 0 6px 0;';

const bullets = (arr) => "<ul style='margin:0 0 12px 0;padding-left:20px;'>" + arr.map((x) => "<li style='" + li + "'>" + x + "</li>").join('') + '</ul>';

const memo_html =
  "<div style='" + wrap + "'>" +
  "<div style='font-family:Arial,Helvetica,sans-serif;font-size:14px;font-weight:700;color:#000000;margin:0 0 6px 0;'>My Soul</div>" +
  "<div style='font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#000000;margin:0 0 18px 0;line-height:1.55;'>" + SUB + '</div>' +
  "<hr style='border:0;border-top:1px solid #e3e7ec;margin:18px 0;'>" +
  "<p style='" + p + "'>Revenue is expected to grow from a projected INR 1.5 Cr in FY26 to INR 24.6 Cr by FY28, approximately 16.4x over two years (305% CAGR), with CM2 positive targeted by FY26 and EBITDA positive by FY27. My Soul is a science-backed sexual wellness brand built for a category India buys but does not discuss. It sells 30 SKUs across delay sprays and gels, lubricants, condoms, massagers and wellness capsules, formulated on a combined Ayurveda and allopathy approach, and manufactured under GMP, HACCP, FDA, ISO, AYUSH, FSSAI and drug-licence standards. The commercial insight is distribution, not product: quick commerce solved the discretion problem that kept this category in back-alley pharmacies, and My Soul built for that channel first. Operated by Raisha Brands Pvt Ltd.</p>" +
  "<div style='" + h + "'>1. Traction</div>" +
  bullets([
    'Revenue run-rate INR 2.2 Cr (October 2025 annualised), up from INR 3.2 lakh a month in January 2025',
    'MRR growth 4.5x between April and October 2025',
    'Product margin 84%; contribution margin 40%',
    'AOV INR 325; return rate 6.6%; customer ratings 4/5 across channels',
    'Distribution across 100 cities, ~350 Blinkit dark stores and 25 Swiggy Instamart dark stores',
    'Channel mix: Blinkit 80%, Swiggy Instamart 7%, Flipkart 7%, Amazon 3%, D2C and exports 3%',
    '64% of revenue from ages 18-34; over 80% from Tier 1 cities, led by Maharashtra (35%) and Karnataka (27%)'
  ]) +
  "<p style='" + p + "'>Zepto has offered to onboard My Soul pan-India from December 2025, against a current base of zero Zepto stores - a step-change in reach on the channel that already drives four-fifths of revenue.</p>" +
  "<div style='" + h + "'>2. Founder-Market Fit</div>" +
  "<p style='" + p + "'>This is a distribution and trust problem, not a formulation problem, and the team is built for both halves of it.</p>" +
  bullets([
    '<b>Kunal Singh Chhatwal, Founder &amp; CEO</b> - Christ University and ISB, previously at Amazon and Mensa Brands. Led Amazon international expansion and drove category growth for Samsung and TCL, with deep e-commerce operations and marketplace scaling experience.',
    '<b>Supreet Kaur, Co-Founder &amp; CMO</b> - builds organic growth through UGC, influencer networks and creator-led campaigns, with prior content and inventory ownership across Flipkart Smart Buy and Retail Ez. Leads the women-first side of the brand.'
  ]) +
  "<p style='" + p + "'>Supported by a lean eight-person team and three onboarded specialists - two senior urologists and a head gynaecologist - who anchor the clinical side of the proposition.</p>" +
  "<div style='" + h + "'>3. Key Investment Highlights</div>" +
  bullets([
    '<b>Quick commerce is the unlock, and the position is already won.</b> ' + H1 + '.',
    '<b>Margin structure absorbs growth spend.</b> ' + H2 + ', leaving room for acquisition investment without eroding contribution.',
    '<b>Clinical positioning in a pleasure-led category.</b> ' + H3 + '.',
    '<b>Digital clinic converts a product sale into a subscription.</b> Launching December 2025: free quiz, tele-consult at INR 1,000-3,000, then INR 5,000-10,000 monthly packages with progress tracking.',
    '<b>Category tailwinds are structural.</b> Sexual health teleconsultations rose 200% between 2017 and 2022, 84% of that from Tier-2 cities, against a USD 1.4 Bn market growing to USD 2.5 Bn by 2032.',
    '<b>Channel concentration is the risk to underwrite.</b> 80% of revenue sits on a single platform; Zepto onboarding, Netmeds and Apollo omni-channel expansion, and US and EU online entry are the stated diversification path.'
  ]) +
  "<div style='" + h + "'>4. The Round</div>" +
  "<p style='" + p + "'>INR 8 Cr seed. Deployment: marketing and sales 50%, channel expansion 27%, inventory funding 15%, team hiring 8%. Funds influencer and brand-face partnerships, pan-India quick-commerce expansion to 150+ Blinkit and 100+ Zepto cities, 12 new SKUs, and finance, performance-marketing and sales hires. Milestones: CM2 positive by FY26, EBITDA positive by FY27.</p>" +
  "<div style='" + h + "'>5. Recent Category Funding</div>" +
  "<p style='" + p + "'>Indian sexual wellness has moved from taboo to a funded consumer category on the back of quick commerce. Bold Care raised USD 5M in a Series A and has since scaled to roughly INR 79.5 Cr in revenue. MyMuse raised USD 2.7M in pre-Series A, having earlier raised INR 9.5 Cr. Both are pleasure-led and, until recently, single-gender at launch. My Soul is positioned differently by entering as a clinical proposition for men and women together, with a doctor-led digital clinic layered onto the product business rather than sold separately.</p>" +
  '</div>';

const memo_body = 'My Soul - ' + SUB + '. Science-backed sexual wellness brand, 30 SKUs across delay sprays and gels, lubricants, condoms, massagers and wellness capsules, on a combined Ayurveda and allopathy approach under seven certification regimes. Revenue run-rate INR 2.2 Cr (Oct 2025 annualised), 4.5x MRR growth Apr-Oct 2025, 84% product margin, 40% contribution margin, AOV INR 325, return rate 6.6%. Blinkit 80% of revenue with first rank on high-intent search; Zepto pan-India onboarding offered from December 2025. INR 8 Cr seed; CM2 positive by FY26, EBITDA positive by FY27. Operated by Raisha Brands Pvt Ltd.';

return [{ json: {
  startup: NAME,
  owner: 'Aditya',
  sector: SECTOR,
  stage: 'Traction',
  raise_inr_cr: 'INR 8 Cr',
  revenue: 'INR 2.2 Cr run-rate (Oct 2025 annualised)',
  send_day: '',
  deck_link: 'https://bit.ly/PDmysoul-updated',
  highlight_1: H1,
  highlight_2: H2,
  highlight_3: H3,
  active: 'Yes',
  memo_body: memo_body,
  memo_html: memo_html,
} }];

const NAME = 'My Soul';
const OWNER = 'Aditya';
const NEXT_DUE = '2026-09-04';
const SCORE = 85;
const NOTE = 'Very High match (85)';

let startupExists = false;
for (const s of $('Read STARTUPS').all()) { if (String(s.json.startup || '').trim().toLowerCase() === NAME.toLowerCase()) { startupExists = true; } }
if (!startupExists) { throw new Error('My Soul is not in STARTUPS yet - aborting'); }
for (const pr0 of $('Read PIPELINE').all()) { if (String(pr0.json.startup || '').trim().toLowerCase() === NAME.toLowerCase()) { throw new Error('PIPELINE already has My Soul rows - aborting'); } }

const TARGETS = ['12 Flags VC','Aakash Emprise','Anicut Capital','Artha Venture Fund','Atomic Capital','Chiratae ventures','DSG Consumer Partners','Equanimity Investments','Equentis','Fireside Ventures','Flipkart Ventures','Hem Angels','Huddle Ventures','IAN Group (Indian Angel Network)','Inflection Point Ventures','Kae Capital','Kairon Capital','Kemfin Family Office',"L'Oreal Venture Capital",'M Venture Partners','Narotam Sekhsaria Family Office','Orios Venture Partners','Prath Ventures','Rebalance','Rukam Capital','Sharrp Ventures','Sorin Investments','Udyat Ventures','V3 Ventures','Venture Catalysts','Windrose Capital','Wipro','Wipro Consumer Care Ventures','Zeren Capital'];

const invByName = {};
for (const v of $('Read INVESTORS').all()) {
  const n = String(v.json.investor || '').trim();
  if (n && invByName[n] === undefined) { invByName[n] = v.json; }
}

let maxId = 0;
for (const pr of $('Read PIPELINE').all()) {
  const m = String(pr.json.deal_id || '').trim().match(/^D(\d+)$/);
  if (m) { const n = parseInt(m[1], 10); if (n > maxId) maxId = n; }
}

const out = [];
let seq = maxId;
for (const name of TARGETS) {
  const inv = invByName[name];
  if (!inv) { throw new Error('Investor not found in INVESTORS: ' + name); }
  if (String(inv.do_not_contact || '').trim().toLowerCase() === 'yes') { throw new Error('Investor is do_not_contact: ' + name); }
  const email = String(inv.email || '').trim();
  if (email === '') { throw new Error('Investor has no email: ' + name); }
  seq++;
  out.push({ json: {
    deal_id: 'D' + String(seq).padStart(5, '0'),
    startup: NAME,
    owner: OWNER,
    investor: name,
    email: email,
    cc: String(inv.cc || '').trim(),
    priority: SCORE,
    deal_shared: 'No',
    next_action: 'Initial',
    next_due: NEXT_DUE,
    notes: NOTE,
  } });
}
if (out.length !== TARGETS.length) { throw new Error('Row count mismatch - aborting'); }
return out;
